namespace detail {

inline std::vector<uint8_t> make_error(const std::string &message) {
  msgpack::sbuffer buf;
  msgpack::packer<msgpack::sbuffer> pk(buf);
  pk.pack_array(2);
  pk.pack(std::string("EchoErrorResponse"));
  pk.pack_map(1);
  pk.pack(std::string("message"));
  pk.pack(message);
  return std::vector<uint8_t>(buf.data(), buf.data() + buf.size());
}

} // namespace detail

template <typename Ctx>::ipc::Handler make_echo_handler(Ctx &ctx) {
  using HandlerFn =
      std::function<std::vector<uint8_t>(Ctx &, const msgpack::object &)>;
  static const std::unordered_map<std::string, HandlerFn> table = {
      {"EchoBytes",
       [](Ctx &ctx, [[maybe_unused]] const msgpack::object &payload)
           -> std::vector<uint8_t> {
         wire::EchoBytes wire_cmd;
         payload.convert(wire_cmd);
         auto wire_resp = handle_bytes(ctx, std::move(wire_cmd));
         msgpack::sbuffer buf;
         msgpack::packer<msgpack::sbuffer> pk(buf);
         pk.pack_array(2);
         pk.pack(std::string("EchoBytesResponse"));
         pk.pack(wire_resp);
         return std::vector<uint8_t>(buf.data(), buf.data() + buf.size());
       }},
      {"EchoFields",
       [](Ctx &ctx, [[maybe_unused]] const msgpack::object &payload)
           -> std::vector<uint8_t> {
         wire::EchoFields wire_cmd;
         payload.convert(wire_cmd);
         auto wire_resp = handle_fields(ctx, std::move(wire_cmd));
         msgpack::sbuffer buf;
         msgpack::packer<msgpack::sbuffer> pk(buf);
         pk.pack_array(2);
         pk.pack(std::string("EchoFieldsResponse"));
         pk.pack(wire_resp);
         return std::vector<uint8_t>(buf.data(), buf.data() + buf.size());
       }},
      {"EchoNested",
       [](Ctx &ctx, [[maybe_unused]] const msgpack::object &payload)
           -> std::vector<uint8_t> {
         wire::EchoNested wire_cmd;
         payload.convert(wire_cmd);
         auto wire_resp = handle_nested(ctx, std::move(wire_cmd));
         msgpack::sbuffer buf;
         msgpack::packer<msgpack::sbuffer> pk(buf);
         pk.pack_array(2);
         pk.pack(std::string("EchoNestedResponse"));
         pk.pack(wire_resp);
         return std::vector<uint8_t>(buf.data(), buf.data() + buf.size());
       }},
      {"EchoShutdown",
       []([[maybe_unused]] Ctx &ctx,
          [[maybe_unused]] const msgpack::object &payload)
           -> std::vector<uint8_t> {
         msgpack::sbuffer buf;
         msgpack::packer<msgpack::sbuffer> pk(buf);
         pk.pack_array(2);
         pk.pack(std::string("EchoShutdownResponse"));
         pk.pack_map(0);
         THROW ::ipc::ShutdownRequested(
             std::vector<uint8_t>(buf.data(), buf.data() + buf.size()));
       }},
  };

  return
      [&ctx](const std::vector<uint8_t> &raw_request) -> std::vector<uint8_t> {
        auto unpacked =
            msgpack::unpack(reinterpret_cast<const char *>(raw_request.data()),
                            raw_request.size());
        auto obj = unpacked.get();

        if (obj.type != msgpack::type::ARRAY || obj.via.array.size != 1) {
          std::cerr << "Error: Expected array of size 1\n";
          return {};
        }

        auto &inner = obj.via.array.ptr[0];
        if (inner.type != msgpack::type::ARRAY || inner.via.array.size != 2 ||
            inner.via.array.ptr[0].type != msgpack::type::STR) {
          std::cerr << "Error: Expected [CommandName, {payload}]\n";
          return {};
        }

        std::string cmd_name(inner.via.array.ptr[0].via.str.ptr,
                             inner.via.array.ptr[0].via.str.size);
        auto &cmd_payload = inner.via.array.ptr[1];

        auto it = table.find(cmd_name);
        if (it == table.end()) {
          return detail::make_error("unknown command: " + cmd_name);
        }
#ifdef BB_NO_EXCEPTIONS
        return it->second(ctx, cmd_payload);
#else
        try {
          return it->second(ctx, cmd_payload);
        } catch (const ::ipc::ShutdownRequested &) {
          throw;
        } catch (const std::exception &e) {
          std::cerr << "Error processing " << cmd_name << ": " << e.what()
                    << '\n';
          return detail::make_error(e.what());
        }
#endif
      };
}

template <typename Ctx>
void serve(const char *socket_path, Ctx &ctx,
           std::atomic<bool> *shutdown_flag = nullptr) {
  ::ipc::serve(socket_path, make_echo_handler(ctx), shutdown_flag);
}

